    val installHint: String,
    /** Whether PPM can install this one on *this host* — a toolchain-based install needs that toolchain. */
    val installable: Boolean? = null,
    /** What the install would use, so the dialog can say what pressing the button does. */
    val installWith: String? = null,
)

/** The server a document is being served by. */
@Serializable
data class LspServerInfo(
    val id: String,
    val displayName: String,
    val rootPath: String,
)

@Serializable
data class SessionInfo(
    val id: String,
    val providerId: String,
    val title: String,
    val projectName: String? = null,
    val createdAt: String,
    val updatedAt: String? = null,
    val pinned: Boolean? = null,
    val tag: Tag? = null,
    /** Design this session belongs to; null/absent for an ordinary chat. */
    val designSlug: String? = null,
    /** The session whose AI created this one; null/absent when a person started it. */
    val spawnedBy: String? = null,
    /** That session's title, when PPM has one for it. */
    val parentTitle: String? = null,
) {
    @Serializable
    data class Tag(
        val id: Int,
        val name: String,
        val color: String,
    )
}

/** What one compaction did, read back from the `compact_boundary` record Claude Code writes into the transcript. Taken from the file rather than from the live `compact_boundary` event because the figure has to survive a reload: the turn that compacts ends by refetching history, so a notice that existed only in WebSocket state would vanish seconds after it appeared. The event carries the same numbers and is deliberately not plumbed. */
@Serializable
data class CompactionInfo(
    /** `auto` when the context window forced it, `manual` when the user ran /compact. */
    val trigger: String,
    /** Transcript size going in. */
    val preTokens: Double,
    /** Size of the summary that replaced it. */
    val postTokens: Double,
    /** `preTokens - postTokens` — this compaction alone, not the session's running total. */
    val savedTokens: Double,
    /** How long the compaction took, when the record says. */
    val durationMs: Double? = null,
)

@Serializable
data class ChatMessage(
    val id: String,
    val role: String,
    val content: String,
    val events: List<ChatEvent>? = null,
    val timestamp: String,
    /** Account used to generate this assistant message */
    val accountId: String? = null,
    val accountLabel: String? = null,
    /** SDK message UUID — used for fork/rewind (maps to JSONL message IDs) */
    val sdkUuid: String? = null,
    /** Token split for the turn that produced this message; drives the cost warning. */
    val usage: TurnUsage? = null,
    /** Set only on the compact-summary message that opens a post-compaction segment, so the divider above it can say what the compaction cost and saved. */
    val compaction: CompactionInfo? = null,
    /** The turn this message belongs to: the id of the prompt that opened it (Claude: that record's `promptId`, or `u:<uuid>` when it has none; Codex: the native `turn_id`). Stamped by the history paths from the session's turn index (`session-turns/`). */
    val turnId: String? = null,
    /** That turn's number, counted from the start of the session — compacted segments included. */
    val turnN: Double? = null,
    /** Browser only: the id the sending browser gave a live user message (`clientMessageId`), which `turn_started` hands back with the turn it opened. Never in history. */
    val clientId: String? = null,
    /** A copy of earlier history a Codex compaction wrote back into the thread, not something anyone said at that point. Never a turn, never numbered. */
    val synthetic: Boolean? = null,
    /** A user record the CLI wrote rather than the person: a meta record, a compaction summary, a transcript-only copy, a task notification. Read from the record's own flags, which the text alone does not show, so it is never mistaken for a prompt (`shared/user-prompt-kind.ts`). */
    val notPrompt: Boolean? = null,
)

/** One group of edited versions of the same user message. Part of the GET /chat/sessions/:id/messages response, keyed by user-message ordinal. */
@Serializable
data class VersionGroup(
    /** Ordered version session ids: parent (v1 / original) first, then children oldest-first. */
    val ids: List<String>,
    /** Position of the queried session within `ids`. */
    val currentIndex: Int,
)

/** One browser that receives push, as the Settings pane lists it. Keys never leave the server. */
@Serializable
data class PushDeviceInfo(
    val id: String,
    val label: String,
    /** The push service URL. Not a secret without the server's VAPID key; it is how a browser finds its own row. */
    val endpoint: String,
    val origin: String,
    val createdAt: Double,
    val lastSuccessAt: Double? = null,
    val lastError: String? = null,
)
